        # 25 = 5*5 -> excluded
        self.assertEqual(
            words_in_sentence("aaaaabbbbbcccccdddddeeeee"),
            "",
        )

    def test_empty_string(self):
        self.assertEqual(words_in_sentence(""), "")

    def test_only_non_prime_words_returns_empty(self):
        self.assertEqual(words_in_sentence("one four nine"), "")

    def test_preserves_order(self):
        self.assertEqual(words_in_sentence("zebra cat ox dog bat"), "cat ox bat")

    def test_multiple_spaces_between_words(self):
        # split() handles extra whitespace
        self.assertEqual(words_in_sentence("hi   there     ok"), "hi ok")


